[3082] = { en = "Etched Tablet", tier = 1,
  t = "Gegraveerde tablet",
  d = "Ah, terwijl je weg was, is er een tablet voor je gekomen, $N.$B$BLees hem als je tijd hebt. Als ik me niet vergis, komt hij van de jagerstrainer Jen'shan. Ze wil met je praten als je klaar bent.",
  o = "Praat met Jen'shan in de Valley of Trials.",
  p = "Jen'shan ziet een machtige $C voor zich, en de geesten zijn tevreden.$b$bHet pad van de $C is een van onze oudste manieren van leven. De Horde kwam naar ons toen ze nog vochten om te overleven op Azeroth. Ze vroegen ons om hen te onderwijzen, om hun de geheimen van veel dingen te laten zien. Ze waren al sterk: sterk op de manier van de $C; sterk op de manier van de $C. Maar het pad van de $C was niet hun pad... toen nog niet.",
  c = "Nu leren wij hun die dingen, en zij leren ons andere dingen. We worden één volk... bijna. We zijn al lang bondgenoten. Dus vergeet niet om hen te helpen. En Jen'shan vergeet niet om jou te helpen.$b$bJen'shan leert je de wegen van de $C. Ze leert het je goed. Vergeet nooit: de stam heeft veel respect voor een $C. Jij krijgt een grote rol in de toekomst... vergeet dat nooit.$b$bAls je het nodig hebt, kom dan naar Jen'shan. Ze leert je zoveel als ze kan, wanneer ze voelt dat je klaar bent.",
  g = { {"gegraveerde", "etched, engraved (gegraveerd)"}, {"vergis", "am mistaken (zich vergissen)"}, {"jagerstrainer", "hunter trainer"}, {"geesten", "spirits (geest)"}, {"overleven", "survive"}, {"onderwijzen", "teach"}, {"geheimen", "secrets (geheim)"}, {"bondgenoten", "allies (bondgenoot)"}, {"stam", "tribe"}, {"respect", "respect"}, {"toekomst", "future"} },
},

[3083] = { en = "Encrypted Tablet", tier = 1,
  t = "Gecodeerde tablet",
  d = "Ah, terwijl je weg was, is er een tablet voor je gekomen, $N.$B$BLees hem als je tijd hebt. Als ik me niet vergis, komt hij van de schurkentrainer Rwag. Hij wil met je praten als je klaar bent.",
  o = "Lees de Encrypted Tablet en praat met Rwag in de Valley of Trials.",
  p = "Welkom in de Valley of Trials, $N. Je zou hier niet zijn als je mijn tablet niet had gekregen, dus ik kom meteen ter zake.$B$BIk ben Rwag en ik train de schurken, dieven en zakkenrollers hier in de Valley. Ik ben degene die de Hand aanspreekt als jij niet klaar bent voor wat er gaat komen. Maar maak je geen zorgen: de Hand bepaalt niet alles wat je doet. Toch is het slim om met hen samen te werken als ze je talenten nodig hebben.",
  c = "Tot het zover is, sta je onder mijn leiding. Ik leer je de kneepjes van het vak, zoals sommige mensen zeggen. Kom naar mij als je je klaar voelt, dan kijk ik of ik je verder kan trainen. Oefen tot die tijd je vaardigheden en houd ze zo scherp als een scheermes. Je weet nooit wanneer je zelfs de kleinste vaardigheid nodig hebt.",
  g = { {"gecodeerde", "encrypted (gecodeerd)"}, {"schurkentrainer", "rogue trainer"}, {"ter zake", "to the point"}, {"schurken", "rogues (schurk)"}, {"dieven", "thieves (dief)"}, {"zakkenrollers", "pickpockets, cutpurses (zakkenroller)"}, {"aanspreekt", "holds responsible, addresses (aanspreken)"}, {"bepaalt", "decides, controls (bepalen)"}, {"leiding", "guidance"}, {"de kneepjes van het vak", "the tricks of the trade, the ropes"}, {"scheermes", "razor"} },
},

[3087] = { en = "Etched Parchment", tier = 1,
  t = "Gegraveerd perkament",
  d = "Ah, terwijl je weg was, is er een perkament voor je gekomen, $N.$B$BLees het als je tijd hebt. Als ik me niet vergis, komt het van de jagerstrainer Jen'shan. Ze wil met je praten als je klaar bent.",
  o = "Lees het Etched Parchment en praat met Jen'shan in de Valley of Trials.",
  p = "Ah, dus je komt eindelijk. Goed. Jen'shan wacht op je.$B$BVeel mensen denken dat het een makkelijk pad is, maar Jen'shan zegt je: dat is niet waar. De dieren van Durotar en verder beheersen vraagt net zoveel vaardigheid als de arcane kunsten beheersen of met onze voorouders praten.$B$BSchieten met een boog of geweer is voor jou misschien niet zo gevaarlijk als een spreuk uitspreken. Maar voor je vijand is het zeker net zo gevaarlijk.",
  c = "Als we klaar zijn met praten, moet je met de andere bewoners van de Valley praten. Ze vragen je om dingen voor hen te doen... dingen die je vaardigheid testen en je een paar gevaren van dit land leren.$B$BAls je groeit in ervaring en wijsheid, heb je Jen'shan nodig om je betere technieken en vaardigheden te laten zien. Kom vaak terug naar Jen'shan. Ik laat je weten wat ik je kan leren.",
  g = { {"perkament", "parchment"}, {"eindelijk", "at last"}, {"beheersen", "master, control"}, {"vaardigheid", "skill"}, {"arcane kunsten", "arcane arts"}, {"voorouders", "ancestors (voorouder)"}, {"geweer", "rifle, gun"}, {"spreuk", "spell"}, {"bewoners", "inhabitants (bewoner)"}, {"gevaren", "dangers (gevaar)"}, {"wijsheid", "wisdom"} },
},

[3088] = { en = "Encrypted Parchment", tier = 1,
  t = "Gecodeerd perkament",
  d = "Ah, terwijl je weg was, is er een perkament voor je gekomen, $N.$B$BLees het als je tijd hebt. Als ik me niet vergis, komt het van de schurkentrainer Rwag. Hij wil met je praten als je klaar bent.",
  o = "Lees het Encrypted Parchment en praat met Rwag in de Valley of Trials.",
  p = "Sst, niet zo hard. Ik vertrouw Nartok daar niet. Met iemand die zich nog dieper in een grot moet verstoppen dan ik, moet je niet spotten.$b$bIk neem aan dat je zonder problemen de weg hebt gevonden?",
  c = "Nu je weet waar ik me verstop, moet ik je iets vertellen: de Shattered Hand heeft me gevraagd om op je te letten. Ze willen dat ik je train en je op de hoogte houd van alles wat ze nodig hebben. Ook als je hen nog niet wilt helpen (en je bent dom als je dat niet wilt), doe ik wat ik kan om je te trainen... voor een klein bedrag. Kom terug wanneer je denkt dat je klaar bent, dan kijken we wat je kunt leren.",
  g = { {"gecodeerd", "encrypted"}, {"vertrouw", "trust (vertrouwen)"}, {"verstoppen", "hide"}, {"spotten", "trifle, mess (with)"}, {"neem aan", "assume (aannemen)"}, {"verstop", "hide (verstoppen)"}, {"letten", "watch, pay attention (letten op)"}, {"op de hoogte houd", "keep informed (op de hoogte houden)"}, {"bedrag", "sum, fee"} },
},

[3092] = { en = "Etched Note", tier = 1,
  t = "Gegraveerd briefje",
  d = "Een moment geleden zocht een boodschapper naar je, $N. Ik denk dat de jagerstrainer Lanka haar heeft gestuurd. Als dit briefje van Lanka komt, zou ik het snel lezen.$b",
  o = "Lees de Etched Note en praat met Lanka Farshot in Red Cloud Mesa.",
  p = "Welkom in Camp Narache, $N. Ik hoor goede dingen over je. Je bloedlijn is sterk, en veel van de oudsten vinden je nu al vaardig. Maar dat gaan we testen.$B$BDe vlaktes van Mulgore zijn een tijd lang je thuis. Je moet je best doen om ze heel goed te leren kennen. Op een dag reis je naar onbekende landen om grotere vaardigheden te leren. Je moet klaar zijn.",
  c = "En het is mijn taak om ervoor te zorgen dat je voorbereid bent. Ik leer je de basis van ons vak: hoe je je huisdier temt, hoe je met je geweer schiet, en veel andere vaardigheden die je nodig zult hebben.$b$bJagers zijn een sterk deel van onze traditie en geschiedenis, $N. Onthoud goed hoe belangrijk je bent voor de stam. Men zal je respecteren en vereren als je ons volk goed dient.",
  g = { {"boodschapper", "messenger"}, {"briefje", "note"}, {"bloedlijn", "bloodline"}, {"oudsten", "elders (oudste)"}, {"vaardig", "skilled"}, {"vlaktes", "plains (vlakte)"}, {"onbekende", "unfamiliar (onbekend)"}, {"voorbereid", "prepared (voorbereiden)"}, {"vak", "profession, trade"}, {"temt", "tame (temmen)"}, {"vereren", "revere"}, {"dient", "serve (dienen)"} },
},

[3096] = { en = "Encrypted Scroll", tier = 1,
  t = "Gecodeerde rol",
  d = "Ah, terwijl jij bezig was met de hersenloze Scourge, kwam deze rol voor je. Ik denk dat het iets belangrijks is, want het lijkt erop dat hij het zegel draagt van de schurkentrainer David Trias. Ik zou de tijd nemen om hem te lezen voordat je weer vertrekt.",
  o = "Lees de Encrypted Scroll en praat met David Trias in Deathknell.",
  p = "Dus je hebt het gehaald? Goed. We hebben in de loop van de tijd meer schurken nodig. De Shadowstalkers vinden je waarschijnlijk als zij denken dat het tijd is. Dus maak geen fouten en doe niets waar je spijt van kunt krijgen. Ze hebben getalenteerde agenten nodig... geen zakkenrollers en dwazen.",
  c = "Ik ben meestal hier in de herberg. Ik let op nieuwe gezichten en houd de veelbelovende nieuwkomers in de gaten. Blijf uit de problemen, dan doe ik wat ik kan om je een paar dingen te leren. Kom gewoon terug wanneer je wilt, dan kijken we of je klaar bent voor een nieuwe vaardigheid of twee.",
  g = { {"hersenloze", "mindless (hersenloos)"}, {"rol", "scroll"}, {"zegel", "seal"}, {"in de loop van de tijd", "as time goes on"}, {"spijt", "regret"}, {"getalenteerde", "talented (getalenteerd)"}, {"dwazen", "fools (dwaas)"}, {"herberg", "inn"}, {"veelbelovende", "promising (veelbelovend)"}, {"in de gaten", "keep an eye on (in de gaten houden)"}, {"Blijf uit de problemen", "keep out of trouble"} },
},

[1859] = { en = "Therzok", tier = 1,
  t = "Therzok",
  d = "Praat zachter, $n. Ja, ik ken je naam. Ik moest uitkijken naar een orc die eruitziet zoals jij.$b$bWe hebben gehoord dat je jezelf kunt redden in een gevecht. En dat je af en toe niet tegen een beetje stiekem gedoe bent.$b$bHeb ik gelijk?$b$bHoe dan ook, je moet naar Therzok in Orgrimmar gaan. Hij heeft een aanbod waar je naar moet luisteren.",
  o = "Praat met Therzok in de Cleft of Shadow in Orgrimmar.",
  c = "Heel goed. Ik ben blij dat Kaplak je heeft kunnen vinden.$b$bWe moeten over een paar dingen praten, en zeker over je toekomst bij de Hand.",
  g = { {"zachter", "more quietly (zacht)"}, {"uitkijken", "look out (for)"}, {"eruitziet", "looks (eruitzien)"}, {"jezelf kunt redden", "can handle yourself (zich redden)"}, {"af en toe", "from time to time"}, {"stiekem", "sneaky"}, {"gedoe", "business, stuff"}, {"Hoe dan ook", "anyway"}, {"aanbod", "offer"} },
},

[1885] = { en = "Mennet Carkad", tier = 1,
  t = "Mennet Carkad",
  d = "$n? Niet helemaal wat ik verwachtte, nu Carkad zelf interesse in je heeft. Maar de schijn kan bedriegen, toch?$b$bHoe dan ook, je moet zo snel mogelijk naar hem toe gaan. Je wilt niet weten wat er gebeurde met de laatsten die zijn oproep negeerden.",
  o = "Praat met Mennet Carkad in de Rogues' Quarter van de Undercity.",
  c = "Hm. Je bent zeker meteen hierheen gekomen toen je over mijn oproep hoorde, ja? Natuurlijk. Ik verwacht niet minder van iemand die een Deathstalker wil worden.",
  g = { {"verwachtte", "expected (verwachten)"}, {"de schijn kan bedriegen", "looks can be deceiving"}, {"zo snel mogelijk", "as soon as possible"}, {"oproep", "summons, call"}, {"negeerden", "ignored (negeren)"}, {"meteen", "right away"} },
},

[6061] = { en = "Taming the Beast", tier = 1,
  t = "Het beest temmen",
  d = "Als tauren is het belangrijk om de tradities van onze voorouders te volgen door tegen machtige wezens te vechten. Als we deze wezens verslaan, kunnen we hun geest in ons opnemen. Zo komen we dichter bij de Earthmother.$B$BOp dezelfde manier helpt het temmen van een beest dat naast ons vecht ons om één te worden met de natuur om ons heen. Later leer je een beest naar keuze te temmen. Maar alles vraagt oefening, en je moet nog veel leren. Begin met deze Taming Rod. Je moet een Adult Plainstrider temmen.",
  o = "Gebruik de Taming Rod om een Adult Plainstrider te temmen. Oefen je vaardigheden en breng de Taming Rod dan terug naar Yaw Sharpmane in Bloodhoof Village.",
  p = "Oefen je vaardigheden, $N. Tem de Adult Plainstrider.",
  c = "De Earthmother heeft me tekens gestuurd. Je hebt het goed gedaan.",
  e = "Tem een Adult Plainstrider",
  g = { {"temmen", "tame"}, {"voorouders", "ancestors (voorouder)"}, {"wezens", "creatures (wezen)"}, {"verslaan", "defeat"}, {"opnemen", "take in"}, {"naar keuze", "of your choice"}, {"oefening", "practice"}, {"Tem", "tame (temmen)"}, {"tekens", "signs (teken)"} },
},

[6062] = { en = "Taming the Beast", tier = 1,
  t = "Het beest temmen",
  d = "Het is een bewonderenswaardige vaardigheid om de natuur onder je gezag te brengen. Als jager moet je proberen de kracht en macht te leren gebruiken die in elk wezen van je keuze zit.$B$BControle krijgen over een dier is niet makkelijk. Het is een taak die je met veel doorzettingsvermogen moet doen.$B$BVoor je eerste opdracht: neem deze Taming Rod en tem er een Dire Mottled Boar mee. Je vindt ze heel dicht bij Razor Hill. Oefen je vaardigheden in een gevecht met het zwijn aan je zij, en kom dan terug naar mij.",
  o = "Gebruik de Taming Rod om een Dire Mottled Boar te temmen. Oefen je vaardigheden en breng de Taming Rod dan terug naar Thotar in Razor Hill.",
  p = "Veel succes, jonge $C.",
  c = "Je hebt het goed gedaan, $N. Ik denk dat je klaar bent voor je volgende taak.",
  e = "Tem een Dire Mottled Boar",
  g = { {"bewonderenswaardige", "admirable (bewonderenswaardig)"}, {"gezag", "authority"}, {"macht", "power"}, {"keuze", "choice"}, {"doorzettingsvermogen", "determination, perseverance"}, {"opdracht", "assignment"}, {"tem", "tame (temmen)"}, {"zwijn", "boar"}, {"aan je zij", "at your side"} },
},

